Given a string str, find the smallest window length that contains all the characters of the given string at least one time.Examples: Input: str = "aabcbcdbca"Output: 4Explanation: Sub-string -> "dbca"Input: str = "aaab"Output: 2Explanation: Sub-string -> "ab"Try It YourselfTable of Content[Naive Approach] - Generating All Substrings - O(n ^ 2) Time and O(1) Space[Expected Approach] - Using Sliding Window - O(n) Time and O(1) Space[Naive Approach] - Generating All Substrings - O(n ^ 2) Time and O(1) SpaceUse a count array to identify all the unique characters in the string.Generate substrings using two pointers and track characters using a visited array.Check whether the current substring contains all distinct characters.If it does, update the minimum length of the substring found so far.
            C++

    #include <iostream>
using namespace std;

int findSubString(string &str) {
    int n = str.size();

    int ans = n;

    // to store all distinct characters
    vector<bool> visited(26, false);
    for (int i = 0; i < n; i++) {
        visited[str[i]-'a'] = true;
    }

    for(int i = 0; i < n; i++) {
        vector<bool> cur(26, false);

        for(int j = i; j < n; j++) {
            cur[str[j]-'a'] = true;

            // if all characters are present
            if(cur == visited) {
                ans = min(ans, j - i + 1);
                break;
            }
        }
    }

    return ans;
}

int main() {
    string str = "aabcbcdbca";
    cout << findSubString(str);
    return 0;
}


